(async()=>{await HorseArt.ready;window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent||e.data?.type!=='shop-horse-preview')return;const entries=(e.data.entries||[]).slice(0,80).map(({id,look})=>({id,svg:mascot(look.ride||'horse',{silk:look.silk,coat:look.coat,gear:gearFor(look),size:380,still:true}).replaceAll('href="horse-pieces/','href="races/horse-pieces/')}));parent.postMessage({type:'shop-horse-art',key:e.data.key,entries},location.origin)});parent.postMessage({type:'shop-horse-ready'},location.origin)})();
